# Generate a scalene integer-sided triangle with manageable reduced fractions
# and ensure both DE (incenter line) and UV (A-excenter line) are non-integers.
def gcd(a, b):
    while b:
        a, b = b, a % b
    return abs(a)

for _ in range(10000):
    ab = rng.randint(15, 60)
    ac = rng.randint(15, 60)
    bc = rng.randint(15, 60)
    # Triangle inequality and scalene
    if not (ab + ac > bc and ab + bc > ac and ac + bc > ab):
        continue
    if len({ab, ac, bc}) < 3:
        continue
    # Compute reduced fractions for DE and UV
    num_in = bc * (ab + ac)
    den_in = ab + ac + bc
    g_in = gcd(num_in, den_in)
    num_in_r = num_in // g_in
    den_in_r = den_in // g_in
    num_ex = bc * (ab + ac)
    den_ex = (ab + ac - bc)
    if den_ex <= 0:
        continue  # should not happen due to triangle inequality, but be safe
    g_ex = gcd(num_ex, den_ex)
    num_ex_r = num_ex // g_ex
    den_ex_r = den_ex // g_ex
    # Enforce non-triviality: both are non-integer and denominators not too large
    if den_in_r == 1 or den_ex_r == 1:
        continue
    if den_in_r > 2000 or den_ex_r > 2000:
        continue
    # Additional diversity: avoid very small denominators
    if den_in_r < 3 or den_ex_r < 3:
        continue
    return {'ab': ab, 'ac': ac, 'bc': bc}
# Fallback (rare): choose a known good triple
return {'ab': 21, 'ac': 22, 'bc': 20}

